from pathlib import Path
import json,sys,shutil,hashlib,zipfile
import numpy as np
R=Path(__file__).resolve().parents[1];N=R/'nonvehicle10';old=R/'deliveries/nonvehicle10_and_scene_validation_20261023';new=R/'deliveries/nonvehicle10_and_scene_validation_20261023_with_fid'
sys.path.insert(0,str(R/'tools/report_deps'))
from docx import Document
from docx.shared import Inches
# Fresh report.docx generated by builder, then add the same three figures once.
doc=Document(N/'REPORT.docx')
if len(doc.inline_shapes)==0:
 doc.add_heading('关键可视化对比',1)
 for label,cid in [('绿灯：状态与几何','nonvehicle_01_green_light_urban'),('消防栓：颜色漂移','nonvehicle_07_white_hydrant'),('路锥：补全与薄片','nonvehicle_10_orange_cone')]:doc.add_paragraph(label);doc.add_picture(str(N/'results'/cid/'comparison_orbit.jpg'),width=Inches(6.5))
 doc.save(N/'REPORT.docx')
shutil.copytree(old,new,dirs_exist_ok=True)
for name in ['REPORT.md','REPORT.txt','REPORT.html','REPORT.docx','START_HERE.html']:shutil.copy2(N/name,new/'nonvehicle10'/name)
for p in (N/'docs').glob('*'):
 if p.is_file():shutil.copy2(p,new/'nonvehicle10/docs'/p.name)
for p in (N/'evaluation/fid').glob('*'):
 dst=new/'nonvehicle10/evaluation/fid'/p.name;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dst)
for name in ['evaluate_fid.py','summarize.py']:shutil.copy2(R/'scripts/nonvehicle'/name,new/'reproducibility/nonvehicle'/name)
shutil.copy2(R/'scripts/build_nonvehicle_report.py',new/'reproducibility/build_nonvehicle_report.py')
shutil.copytree(R/'tools/fid_deps/pytorch_fid',new/'reproducibility/fid_implementation/pytorch_fid',dirs_exist_ok=True,ignore=shutil.ignore_patterns('__pycache__'))
for p in (R/'tools/fid_deps').glob('pytorch_fid-*.dist-info/LICENSE'):shutil.copy2(p,new/'reproducibility/fid_implementation/LICENSE')
fid=json.loads((N/'docs/fid_metrics.json').read_text());protocol=json.loads((N/'docs/fid_protocol.json').read_text())
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
checks=[]
for group,rows in protocol['input_sha256'].items():
 for r in rows:assert sha(r['rgb'])==r['rgb_sha256'];assert sha(r['mask'])==r['mask_sha256']
 f=np.load(N/'evaluation/fid'/f'{group}_features.npy');assert f.shape==(10 if group=='source' else 160,2048);assert np.isfinite(f).all()
 checks.append(dict(group=group,input_images=len(rows),feature_shape=list(f.shape)))
oldm=json.loads((old/'nonvehicle10/docs/metrics.json').read_text());newm=json.loads((N/'docs/metrics.json').read_text())
for before,after in zip(oldm['summary'],newm['summary']):
 for k in before:assert before[k]==after[k],k
assert oldm['rows']==newm['rows']
audit=dict(status='PASS',FID_newly_evaluated=True,original_metrics_unchanged=True,input_and_mask_hashes_rechecked=650,features=checks,numerical_audit=fid['numerical_audit'],media_status='All media copied byte-for-byte from prior fully decoded delivery; hashes rechecked below',scope='10 nonvehicles x4 routes; no scene FID and no regenerated assets')
media=list(new.rglob('*.mp4'))
for p in media:assert sha(p)==sha(old/p.relative_to(new))
audit['unchanged_videos']=len(media)
prior=new/'reproducibility/delivery_audit.json'
if prior.exists():prior.rename(new/'reproducibility/delivery_audit_before_fid.json')
(new/'reproducibility/fid_delivery_audit.json').write_text(json.dumps(audit,indent=2))
main=new/'START_HERE.html';s=main.read_text();s=s.replace('<h1>非车辆10例与三场景插入验证</h1>','<h1>非车辆10例与三场景插入验证 · 已补充FID</h1><p>新增FID-2048：R 163.20，H 169.37，B0+1 real 185.97，B0 210.91；越低越好。10张源图对160张环绕图，属于小样本分布诊断。<a href="nonvehicle10/docs/fid_summary.csv">FID表</a> · <a href="nonvehicle10/docs/fid_protocol.json">协议</a></p>');main.write_text(s)
with (new/'README.txt').open('a') as f:f.write('\n2026-10-23新增FID-2048：10源图 vs160环绕图/路线，小样本探索性指标；源特征与渲染特征已包含，权重SHA256与实现已记录。原CLIP/DINO/PSNR/SSIM/LPIPS数值未改变。\n')
(new/'SHA256SUMS.txt').write_text(''.join(sha(p)+'  '+str(p.relative_to(new))+'\n' for p in sorted(new.rglob('*')) if p.is_file() and p.name!='SHA256SUMS.txt'))
archive=new.with_suffix('.zip')
with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for p in sorted(new.rglob('*')):
  if p.is_file():z.write(p,new.name+'/'+str(p.relative_to(new)))
with zipfile.ZipFile(archive) as z:assert z.testzip() is None
archive.with_suffix('.zip.sha256').write_text(sha(archive)+'  '+archive.name+'\n')
print('FID_DELIVERY',archive,archive.stat().st_size,flush=True)
